private lemma final_cancel {𝒞 : Type*} [Category 𝒞]
    {x₀ l₁ l₂ l₃ l₄ l₅ e₁ e₂ e₃ r₁ r₂ r₃ : 𝒞}
    {L₁ : x₀ ⟶ l₁} {L₂ : l₁ ⟶ l₂} {L₃ : l₂ ⟶ l₃} {L₄ : l₃ ⟶ l₄} {L₅ : l₄ ⟶ l₅}
    {a : l₅ ⟶ e₁} {b : e₁ ⟶ e₂} {c : e₂ ⟶ e₃}
    {R₁ : x₀ ⟶ r₁} {R₂ : r₁ ⟶ r₂} {R₃ : r₂ ⟶ r₃} {R₄ : r₃ ⟶ e₃}
    {c' : e₃ ⟶ e₂} {b' : e₂ ⟶ e₁} {a' : e₁ ⟶ l₅}
    (h : L₁ ≫ L₂ ≫ L₃ ≫ L₄ ≫ L₅ ≫ a ≫ b ≫ c = R₁ ≫ R₂ ≫ R₃ ≫ R₄)
    (hcc : c ≫ c' = 𝟙 e₂) (hbb : b ≫ b' = 𝟙 e₁) (haa : a ≫ a' = 𝟙 l₅) :
    L₁ ≫ L₂ ≫ L₃ ≫ L₄ ≫ L₅ = R₁ ≫ R₂ ≫ R₃ ≫ R₄ ≫ c' ≫ b' ≫ a' := by
  rw [← reassoc_of% h, reassoc_of% hcc, reassoc_of% hbb, haa, Category.comp_id]

private lemma isIso_of_isIso_comp4_mid {C : Type*} [Category C] {W₀ X₀ Y₀ Z₀ T₀ : C}
    {a : W₀ ⟶ X₀} {b : X₀ ⟶ Y₀} {c : Y₀ ⟶ Z₀} {d : Z₀ ⟶ T₀}
    (h : IsIso (a ≫ b ≫ c ≫ d)) (ha : IsIso a) (hc : IsIso c) (hd : IsIso d) : IsIso b := by
  haveI := h; haveI := ha; haveI := hc; haveI := hd
  haveI : IsIso (b ≫ c ≫ d) := IsIso.of_isIso_comp_left a (b ≫ c ≫ d)
  exact IsIso.of_isIso_comp_right b (c ≫ d)

private lemma iso_cancel_left {C : Type*} [Category C] {W X Y Z : C}
    (a : W ≅ X) (f : X ≅ Z) (g : X ≅ Y) (h : Y ≅ Z) (H : f = g ≪≫ h) :
    a ≪≫ f = (a ≪≫ g) ≪≫ h := by rw [H, Iso.trans_assoc]

private lemma map_fold₅ {𝒞 𝒟 : Type*} [Category 𝒞] [Category 𝒟] (F : 𝒞 ⥤ 𝒟)
    {x₀ x₁ x₂ x₃ x₄ x₅ : 𝒞} {a : x₀ ⟶ x₁} {k₁ : x₁ ⟶ x₂} {k₂ : x₂ ⟶ x₃} {k₃ : x₃ ⟶ x₄}
    {k₄ : x₄ ⟶ x₅} {z : x₀ ⟶ x₅} (h : a ≫ k₁ ≫ k₂ ≫ k₃ ≫ k₄ = z) :
    F.map a ≫ F.map k₁ ≫ F.map k₂ ≫ F.map k₃ ≫ F.map k₄ = F.map z := by
  rw [← F.map_comp, ← F.map_comp, ← F.map_comp, ← F.map_comp, h]

private noncomputable def modToAb : ModuleCat.{u} (ULift.{u} ℤ) ⥤ Ab.{u} :=
  ModuleCat.restrictScalars (ULift.ringEquiv.symm : ℤ ≃+* ULift.{u} ℤ).toRingHom ⋙
    forget₂ (ModuleCat.{u} ℤ) AddCommGrpCat.{u}

private lemma resRing_hom_eq_res {A B : Y.Opens} (i : B ⟶ A) (g : Γ(Y, A)) :
    Y.presheaf.map i.op g = Y.presheaf.map (homOfLE (leOfHom i)).op g :=
  congrArg (fun (k : B ⟶ A) => Y.presheaf.map k.op g) (Subsingleton.elim _ _)

private lemma res_hom_eq_res (N : Y.Modules) {A B : Y.Opens} (i : B ⟶ A) (x : Γ(N, A)) :
    N.presheaf.map i.op x = N.presheaf.map (homOfLE (leOfHom i)).op x :=
  congrArg (fun (k : B ⟶ A) => N.presheaf.map k.op x) (Subsingleton.elim _ _)

private lemma sectionsCast_self (L : X.Modules) {i : ℕ} (h : i = i) (x : sectionDeg L i) :
    sectionsCast L h x = x := by
  rw [Subsingleton.elim h rfl, sectionsCast_refl, LinearEquiv.refl_apply]

private lemma smul_res_eqToHom_eq_zero {Z : Scheme.{u}} (N : Z.Modules)
    {A B : Z.Opens} (hAB : A = B) {a : Γ(Z, B)}
    (ha : ∀ s : Γ(N, B), a • s = 0) (m : Γ(N, A)) :
    Z.presheaf.map (eqToHom hAB).op a • m = 0 := by
  subst hAB
  simpa using ha m

private lemma tensorObjIsoOfIso_hom {X : Scheme.{u}} {M M' N N' : X.Modules}
    (e : M ≅ M') (e' : N ≅ N') :
    (tensorObjIsoOfIso e e').hom = tensorObj_functoriality e.hom e'.hom := rfl

private lemma tensorObjWhiskerLeftIso_refl (F G : X.Modules) :
    tensorObjWhiskerLeftIso F (Iso.refl G) = Iso.refl _ := by
  rw [tensorObjWhiskerLeftIso_eq]; apply Iso.ext; simp

private lemma tensorObjWhiskerRightIso_eqToIso {F F' : X.Modules} (h : F = F') (G : X.Modules) :
    tensorObjWhiskerRightIso (eqToIso h) G = eqToIso (congrArg (fun Z => sheafTensorObj Z G) h) := by
  subst h; simp [tensorObjWhiskerRightIso_refl]

private lemma tensorObjWhiskerRightIso_refl (F G : X.Modules) :
    tensorObjWhiskerRightIso (Iso.refl F) G = Iso.refl _ := by
  rw [tensorObjWhiskerRightIso_eq]; apply Iso.ext; simp

private lemma tensorObjWhiskerRightIso_trans_assoc {F F' F'' : X.Modules}
    (e : F ≅ F') (f : F' ≅ F'') (G : X.Modules) {W : X.Modules}
    (r : sheafTensorObj F'' G ≅ W) :
    tensorObjWhiskerRightIso e G ≪≫ tensorObjWhiskerRightIso f G ≪≫ r
      = tensorObjWhiskerRightIso (e ≪≫ f) G ≪≫ r := by
  rw [tensorObjWhiskerRightIso_trans, Iso.trans_assoc]

private noncomputable def uTensorEquiv (M N : Type u) [AddCommGroup M] [AddCommGroup N] :
    (M ⊗[ULift.{u} ℤ] N) ≃ₗ[ℤ] (M ⊗[ℤ] N) :=
  TensorProduct.equivOfCompatibleSMul ℤ (ULift.{u} ℤ) ℤ M N

private lemma unit_assemble {C : Type*} [Category C] {A B P1 PD S U : C}
    {a : A ⟶ B} {r1 : B ⟶ P1} {pbu : P1 ⟶ U} {rD : A ⟶ PD} (b : PD ⟶ P1)
    {X : PD ⟶ S} {Y : S ⟶ U}
    (hnat : a ≫ r1 = rD ≫ b) (hcore : b ≫ pbu = X ≫ Y) :
    a ≫ r1 ≫ pbu = (rD ≫ X) ≫ Y := by
  rw [← Category.assoc a, hnat, Category.assoc, hcore, ← Category.assoc]

def pointedDualNumberPoints {k : Type u} [Field k] (X : Over (Spec (.of k)))
    (e : Spec (.of k) ⟶ X.left) :=
  {g : Spec (CommRingCat.of (DualNumber k)) ⟶ X.left //
      g ≫ X.hom = Spec.map (CommRingCat.ofHom (algebraMap k (DualNumber k)))
        ∧ g.base (IsLocalRing.closedPoint (DualNumber k)) = e.base default}

noncomputable def classify {Y : ∀ i, Over (U i).toScheme}
    (R : ∀ i, ((Over.map (U i).ι).op ⋙ F).RepresentableBy (Y i))
    {T : Scheme.{0}} {a : T ⟶ S} {i : ι}
    (g : Over.mk (preRes U a i) ⟶ Y i) :
    F.obj (op (overRes (Over.mk a) (pre U a i))) :=
  F.map (classifyHom U a i).op ((R i).homEquiv g)

lemma hom_ext_of_ι {T : Scheme.{0}} {a : T ⟶ S} {i : ι}
    {A : Over (U i).toScheme} {g₁ g₂ : A ⟶ Over.mk (preRes U a i)}
    (h : g₁.left ≫ (pre U a i).ι = g₂.left ≫ (pre U a i).ι) : g₁ = g₂ := by
  apply CommaMorphism.ext
  · exact (cancel_mono (pre U a i).ι).mp h
  · apply Subsingleton.elim

lemma isGlueIso_pullbackCongr (k : κ) {Z : Scheme.{0}} {ρ σ : Z ⟶ (W k).toScheme}
    (hρσ : ρ = σ) {u : Z ⟶ T.left}
    (hρ : ρ ≫ (W k).ι = u) (hσ : σ ≫ (W k).ι = u) :
    IsGlueIso W y k k hρ hσ ((Scheme.Modules.pullbackCongr hρσ).app (y k).F) := by
  rw [Scheme.Modules.pullbackCongr_app_eqToIso hρσ (y k).F]
  exact isGlueIso_eqToIso (y := y) k hρσ hρ hσ

private noncomputable abbrev pullbackAffineRefinementCover (g' : X' ⟶ X) : X'.OpenCover :=
  (Scheme.OpenCover.affineRefinement (X.affineOpenCover.openCover.pullback₁ g')).openCover

